/**
 * UI checks: one test per check in coverage/<feature>/ui.json, logged in as the check's role.
 * Generated by create-qa-suite — change coverage files, not this file.
 */
import { test } from '@playwright/test';
import { coverage, tags } from '../support/coverage.js';
import { contextFor, openPage, runSteps } from '../support/ui.js';

for (const feature of coverage.features.filter((f) => f.ui.checks.length)) {
  test.describe(`${feature.name} UI`, { tag: tags(feature.name, 'ui') }, () => {
    for (const check of feature.ui.checks) {
      const declare = check.draft ? test.fixme : test;
      declare(check.title, async ({ browser }) => {
        const context = await contextFor(browser, check.role);
        const page = await context.newPage();
        await test.step(`open ${check.start} as ${check.role}`, () => openPage(page, check.start).then(() => undefined));
        await runSteps(page, check.steps, (title, body) => test.step(title, body));
        await context.close();
      });
    }
  });
}
